// Adzuna returns { results: [ { title, company.display_name, location.display_name,
// redirect_url, description (snippet), created, salary_min/max } ] }.
// Same output contract as workflow 01, so the same SQL builder and table apply.
function text(v) { return v === null || v === undefined ? '' : String(v); }
function clean(s) {
  return text(s).replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
function fingerprint(company, title, location) {
  const norm = (v) => text(v).toLowerCase()
    .replace(/\b(inc|llc|ltd|pvt|private|limited|corp|corporation|technologies|solutions|labs|gmbh)\b/g, '')
    .replace(/[^a-z0-9]+/g, ' ').trim();
  const base = [norm(company), norm(title), norm(location)].join('|');
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(base).digest('hex').slice(0, 32);
  } catch (e) {
    let h = 2166136261;
    for (let i = 0; i < base.length; i++) { h ^= base.charCodeAt(i); h = Math.imul(h, 16777619); }
    return 'fnv' + (h >>> 0).toString(16) + base.length;
  }
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const results = Array.isArray(j.results) ? j.results : Array.isArray(j) ? j : [];
  for (const r of results) {
    const title = clean(r.title);
    const company = clean(r.company && (r.company.display_name || r.company));
    const location = clean(r.location && (r.location.display_name || r.location));
    if (!title || !company) continue;
    const salary = r.salary_min || r.salary_max
      ? text(r.salary_min) + '-' + text(r.salary_max) + ' ' + (r.salary_is_predicted ? '(est.)' : '')
      : '';
    out.push({
      source: 'adzuna',
      external_id: text(r.id),
      title,
      company,
      location,
      url: text(r.redirect_url),
      description: clean(r.description),
      salary_text: salary,
      tags: r.category && r.category.label ? [clean(r.category.label)] : [],
      posted_at: r.created || null,
      fingerprint: fingerprint(company, title, location),
    });
  }
}

if (!out.length) return [{ json: { empty: true, note: 'Adzuna returned no results for this query' } }];
return out.map((row) => ({ json: row }));

// One INSERT per 75 rows, with ON CONFLICT DO NOTHING so re-running the
// workflow is safe (idempotency lives in the database, not in the code).
const items = $input.all().map((i) => i.json).filter((r) => r && r.fingerprint);
if (!items.length) return [{ json: { rows: 0, sql: 'SELECT 1;' } }];

const esc = (v) =>
  v === null || v === undefined || v === ''
    ? 'NULL'
    : "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";

const jsonb = (v) =>
  "'" + JSON.stringify(Array.isArray(v) ? v : []).replace(/'/g, "''") + "'::jsonb";

const stamp = (v) => {
  if (!v) return 'NULL';
  const d = new Date(v);
  return isNaN(d.getTime()) ? 'NULL' : "'" + d.toISOString() + "'::timestamptz";
};

const CHUNK = 75;
const chunks = [];
for (let i = 0; i < items.length; i += CHUNK) chunks.push(items.slice(i, i + CHUNK));

return chunks.map((rows, idx) => ({
  json: {
    chunk: idx + 1,
    rows: rows.length,
    sql:
      'INSERT INTO jobs (source, external_id, title, company, location, url, description, salary_text, tags, fingerprint, posted_at) VALUES ' +
      rows
        .map(
          (r) =>
            '(' +
            [
              esc(r.source),
              esc(r.external_id),
              esc(r.title),
              esc(r.company),
              esc(r.location),
              esc(r.url),
              esc(r.description),
              esc(r.salary_text),
              jsonb(r.tags),
              esc(r.fingerprint),
              stamp(r.posted_at),
            ].join(',') +
            ')'
        )
        .join(',') +
      ' ON CONFLICT (fingerprint) DO NOTHING RETURNING id;',
  },
}));

const fetched = $('Normalise Adzuna').all().filter((i) => i.json && i.json.fingerprint).length;
const offered = $('Build SQL chunks').all().reduce((n, i) => n + (i.json.rows || 0), 0);
let inserted = 0;
for (const i of $input.all()) {
  const j = i.json || {};
  if (Array.isArray(j)) inserted += j.length;
  else if (Array.isArray(j.rows)) inserted += j.rows.length;
  else if (j.id !== undefined) inserted += 1;
}
return [{ json: { source: 'adzuna', fetched, unique_in_batch: offered, new_rows: inserted, duplicates_skipped: Math.max(offered - inserted, 0) } }];
